SELECT x.n, x.body,
  json_patch(json_patch('{}', json_object('declared', x.declared, 'mode', x.mode, 'session_id', x.session, 'subagent_type', x.asked_type, 'tool_use_id', x.tool_use_id, 'verdict', x.verdict, 'item', x.item, 'owner', x.owner, 'reading', CASE WHEN coalesce(x.read_at, x.error, coalesce(x.disk_path, x.disk_free_gib), coalesce(x.mem_source, x.mem_low, x.mem_avail_pct, x.swap_used_mb, x.mem_total_mb), coalesce(x.slots_dir, x.slots_free, x.slots_held, x.slots_total, (SELECT 1 FROM lane_holders c WHERE c.n = x.n AND c.kind = 'slot' LIMIT 1)), coalesce(x.cpu_source, x.cpu_idle_pct, x.cpu_window_s, x.cpu_samples), coalesce(coalesce(x.pre_cap_from, x.pre_cap), x.pre_total, x.pre_held, x.pre_in_flight, (SELECT 1 FROM lane_holders c WHERE c.n = x.n AND c.kind = 'pre' LIMIT 1), (SELECT 1 FROM lane_owners c WHERE c.n = x.n AND c.kind = 'live' LIMIT 1), (SELECT 1 FROM lane_owners c WHERE c.n = x.n AND c.kind = 'reaped' LIMIT 1)), coalesce(x.weight_in_flight, x.weight_per_core), coalesce(x.load_per_core, x.cores, x.load1), coalesce(coalesce(x.set_load_per_core, x.set_min_free_gib, x.set_min_idle_pct, x.set_max_waiting), x.room_ok, x.room_unread), coalesce(x.waiting_long, x.waiting_short, x.waiting_pre), (SELECT 1 FROM lane_why c WHERE c.n = x.n AND c.kind = 'unread' LIMIT 1)) IS NOT NULL THEN json_object('at', x.read_at, 'error', x.error, 'disk', CASE WHEN coalesce(x.disk_path, x.disk_free_gib) IS NOT NULL THEN json_object('path', x.disk_path, 'free_gib', x.disk_free_gib) END, 'memory', CASE WHEN coalesce(x.mem_source, x.mem_low, x.mem_avail_pct, x.swap_used_mb, x.mem_total_mb) IS NOT NULL THEN json_object('source', x.mem_source, 'low', x.mem_low, 'avail_pct', x.mem_avail_pct, 'swap_used_mb', x.swap_used_mb, 'total_mb', x.mem_total_mb) END, 'slots', CASE WHEN coalesce(x.slots_dir, x.slots_free, x.slots_held, x.slots_total, (SELECT 1 FROM lane_holders c WHERE c.n = x.n AND c.kind = 'slot' LIMIT 1)) IS NOT NULL THEN json_object('dir', x.slots_dir, 'free', x.slots_free, 'held', x.slots_held, 'total', x.slots_total, 'holders', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('repo', c.repo, 'slot', c.slot, 'weight_from', c.weight_from, 'since', c.since, 'weight', c.weight, 'pid', c.pid)) ORDER BY c.ord) FROM lane_holders c WHERE c.n = x.n AND c.kind = 'slot'), '[]'), '{}'))) END, 'cpu', CASE WHEN coalesce(x.cpu_source, x.cpu_idle_pct, x.cpu_window_s, x.cpu_samples) IS NOT NULL THEN json_object('source', x.cpu_source, 'idle_pct', x.cpu_idle_pct, 'window_s', x.cpu_window_s, 'samples', x.cpu_samples) END, 'presteps', CASE WHEN coalesce(coalesce(x.pre_cap_from, x.pre_cap), x.pre_total, x.pre_held, x.pre_in_flight, (SELECT 1 FROM lane_holders c WHERE c.n = x.n AND c.kind = 'pre' LIMIT 1), (SELECT 1 FROM lane_owners c WHERE c.n = x.n AND c.kind = 'live' LIMIT 1), (SELECT 1 FROM lane_owners c WHERE c.n = x.n AND c.kind = 'reaped' LIMIT 1)) IS NOT NULL THEN json_object('cap', CASE WHEN coalesce(x.pre_cap_from, x.pre_cap) IS NOT NULL THEN json_object('from', x.pre_cap_from, 'value', x.pre_cap) END, 'total', x.pre_total, 'held', x.pre_held, 'in_flight', x.pre_in_flight, 'holders', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('repo', c.repo, 'slot', c.slot, 'weight_from', c.weight_from, 'since', c.since, 'weight', c.weight, 'pid', c.pid)) ORDER BY c.ord) FROM lane_holders c WHERE c.n = x.n AND c.kind = 'pre'), '[]'), '{}')), 'live', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('repo', c.repo, 'since', c.since, 'n', c.slot_n, 'pid', c.pid)) ORDER BY c.ord) FROM lane_owners c WHERE c.n = x.n AND c.kind = 'live'), '[]'), '{}')), 'reaped', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('repo', c.repo, 'since', c.since, 'n', c.slot_n, 'pid', c.pid)) ORDER BY c.ord) FROM lane_owners c WHERE c.n = x.n AND c.kind = 'reaped'), '[]'), '{}'))) END, 'cpu_weight', CASE WHEN coalesce(x.weight_in_flight, x.weight_per_core) IS NOT NULL THEN json_object('in_flight', x.weight_in_flight, 'per_core', x.weight_per_core) END, 'load', CASE WHEN coalesce(x.load_per_core, x.cores, x.load1) IS NOT NULL THEN json_object('per_core', x.load_per_core, 'cores', x.cores, 'avg', CASE WHEN x.load1 IS NOT NULL THEN json_array(x.load1, x.load5, x.load15) END) END, 'room', CASE WHEN coalesce(coalesce(x.set_load_per_core, x.set_min_free_gib, x.set_min_idle_pct, x.set_max_waiting), x.room_ok, x.room_unread) IS NOT NULL THEN json_object('settings', CASE WHEN coalesce(x.set_load_per_core, x.set_min_free_gib, x.set_min_idle_pct, x.set_max_waiting) IS NOT NULL THEN json_object('GOH_LANE_LOAD_PER_CORE', x.set_load_per_core, 'GOH_LANE_MIN_FREE_GIB', x.set_min_free_gib, 'GOH_LANE_MIN_IDLE_PCT', x.set_min_idle_pct, 'GOH_LANE_MAX_WAITING', x.set_max_waiting) END, 'ok', CASE x.room_ok WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'unread', CASE x.room_unread WHEN 1 THEN json('true') WHEN 0 THEN json('false') END) END, 'waiting', CASE WHEN coalesce(x.waiting_long, x.waiting_short, x.waiting_pre) IS NOT NULL THEN json_object('long', x.waiting_long, 'short', x.waiting_short, 'pre', x.waiting_pre) END, 'unread', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM lane_why c WHERE c.n = x.n AND c.kind = 'unread'), '[]'), '{}'))) END, 'why', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM lane_why c WHERE c.n = x.n AND c.kind = 'why'), '[]'), '{}')), 'at', strftime('%Y-%m-%dT%H:%M:%S+00:00', x.at, 'unixepoch'))), coalesce(x.rest, '{}')) AS doc
FROM lane_starts x
